    import React from 'react';
    import ReactDOM from 'react-dom/client'; // Для React 18+
    import './index.css'; // Если у вас есть глобальные стили для index.js
    import App from './App'; // Импортируем ваш корневой компонент App

    // Для React 18+
    const root = ReactDOM.createRoot(document.getElementById('root'));
    root.render(
      <React.StrictMode>
        <App />
      </React.StrictMode>
    );

